import { test, expect } from '@playwright/test';

test.describe('Numeric Column Summary Row', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table');
  });

  test('should display summary row with correct total when numeric column has data', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify numeric column header exists
    const numericHeader = page.getByRole('columnheader', { name: /amount/i });
    await expect(numericHeader).toBeVisible();

    // Verify summary row is visible
    const summaryRow = page.getByRole('row', { name: /summary/i });
    await expect(summaryRow).toBeVisible();

    // Verify summary row contains total amount
    const totalAmountCell = page.getByRole('cell', { name: /total/i });
    await expect(totalAmountCell).toContainText('$1,250.00');

    // Verify summary row contains count
    const totalCountCell = page.getByRole('cell', { name: /count/i });
    await expect(totalCountCell).toContainText('15');

    // Verify summary row is at the bottom of the table
    const tableBody = page.getByRole('rowgroup', { name: /table body/i });
    const summaryRowBoundingBox = await summaryRow.boundingBox();
    const tableBodyBoundingBox = await tableBody.boundingBox();
    expect(summaryRowBoundingBox.y).toBeGreaterThan(tableBodyBoundingBox.y);
    expect(summaryRowBoundingBox.y).toBeLessThan(tableBodyBoundingBox.y + 10);
  });

  test('should not display summary row when numeric column is empty', async ({ page }) => {
    // Intercept API call to return empty data
    await page.route('**/api/table/data', route => {
      route.abort();
    });

    // Click on empty state button
    const emptyStateButton = page.getByRole('button', { name: /empty state/i });
    await emptyStateButton.click();

    // Wait for empty state to load
    await page.waitForLoadState('networkidle');

    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify no summary row is displayed
    const summaryRow = page.getByRole('row', { name: /summary/i });
    await expect(summaryRow).not.toBeVisible();

    // Verify empty state message is displayed
    const emptyMessage = page.getByText(/no data available/i);
    await expect(emptyMessage).toBeVisible();

    // Verify total amount cell does not exist
    const totalAmountCell = page.getByRole('cell', { name: /total/i });
    await expect(totalAmountCell).not.toBeVisible();
  });
});
